python3 << 'EOF'
# Let me use a simpler approach - find year headers by looking for patterns
lines = open('/app/resources/treasury_bulletin_1941_05.txt').readlines()

# Find year headers in the first callable section (left side)
# The format is like: | 1941 | nan | nan | nan | 1941 | ...
year_headers = []
for i, line in enumerate(lines):
    # Looking for year header pattern in the left side
    if '| 1941 |' in line and 'nan' in line:
        # Check if it's in the first callable section (column 2 is nan)
        parts = line.split('|')
        if len(parts) >= 5:
            # Second cell should be nan for a year header
            try:
                if 'nan' in parts[2].lower() or parts[2].strip() == '':
                    year_headers.append((1941, i))
            except:
                pass
    elif '| 1944 |' in line and 'nan' in line:
        parts = line.split('|')
        if len(parts) >= 5:
            try:
                if 'nan' in parts[2].lower() or parts[2].strip() == '':
                    year_headers.append((1944, i))
            except:
                pass
    elif '| 1945 |' in line and 'nan' in line:
        parts = line.split('|')
        if len(parts) >= 5:
            try:
                if 'nan' in parts[2].lower() or parts[2].strip() == '':
                    year_headers.append((1945, i))
            except:
                pass

print("Year headers found:", year_headers)

# Now determine which year section each Defense Series belongs to
for i, line in enumerate(lines):
    parts = line.split('|')
    parts = [p.strip() for p in parts if p.strip()]

    if len(parts) > 0 and 'Defense Series' in parts[0]:
        # Find the year section
        year_section = None
        for year, header_line in sorted(year_headers, key=lambda x: -x[1]):
            if header_line < i:
                year_section = year
                break

        print(f"Defense Series at line {i}: year section = {year_section}")
        print(f"  Description: {parts[0]}")
        print(f"  Amount: {parts[1]}")
        print()
